import type { NotificationConfig, NotificationEventKey, NotificationSound } from './types';

/** The six notification events, in the order the Events table lists them. */
export const NOTIFICATION_EVENT_KEYS = [
  'onAgentIdle',
  'onAgentCrash',
  'onPlanComplete',
  'onWorkflowComplete',
  'onWorkflowStalled',
  'onSpawnStalled',
] as const satisfies readonly NotificationEventKey[];

/** The sounds shipped with the app, generated by `scripts/generate-notification-sounds.mjs`. */
export const BUILT_IN_SOUNDS = ['chime', 'rise', 'fall', 'tick'] as const satisfies readonly NotificationSound[];

export const CUSTOM_SOUND_EXTENSIONS = ['wav', 'mp3', 'ogg', 'm4a'] as const;
export const CUSTOM_SOUND_MAX_BYTES = 2 * 1024 * 1024;
/** A custom file longer than this is cut off. */
export const EVENT_SOUND_MAX_MS = 10_000;

/**
 * The notification settings as every decision reads them. While muted, every
 * event switch reads off, so one read silences the event, its taskbar flash and
 * its sound. Mute is a state of this machine, so the saved switches stay as the
 * user set them and return when it is turned off.
 */
export function effectiveNotificationConfig(config: NotificationConfig): NotificationConfig {
  if (!config.muted) return config;
  const desktop = { ...config.desktop };
  const toasts = { ...config.toasts };
  for (const eventKey of NOTIFICATION_EVENT_KEYS) {
    desktop[eventKey] = false;
    toasts[eventKey] = false;
  }
  return { ...config, desktop, toasts };
}

/** The sound an event plays: `off` while muted, and for a custom choice with no file behind it. */
export function resolveEventSound(config: NotificationConfig, eventKey: NotificationEventKey): NotificationSound {
  if (config.muted) return 'off';
  const sound = config.sounds[eventKey];
  if (sound === 'custom' && !config.customSounds[eventKey]) return 'off';
  return sound;
}

export interface DesktopSoundPlan {
  /** Passed to `new Notification`. Undefined leaves the OS default. */
  silent: boolean | undefined;
  /** The main window plays the event's sound beside the notification. */
  playInWindow: boolean;
}

/**
 * How a desktop notification sounds. System is the OS's own sound; every other
 * choice silences the OS so ours is the only one. A notice with no event (a
 * Notify me row) keeps the OS default. With no window to play a chosen sound
 * (macOS, app open with its window closed), the OS sound still tells the user.
 */
export function desktopSoundPlan(sound: NotificationSound | undefined, hasWindow: boolean): DesktopSoundPlan {
  if (sound === undefined) return { silent: undefined, playInWindow: false };
  if (sound === 'off') return { silent: true, playInWindow: false };
  if (sound === 'system') return { silent: false, playInWindow: false };
  return hasWindow ? { silent: true, playInWindow: true } : { silent: false, playInWindow: false };
}
